// in a custom control's renderer
render: function (rm, control) {
  rm.openStart("div", control);
  rm.attr("tabindex", "0");
  rm.accessibilityState(control, {
    role: "switch",
    checked: control.getOn(),
    label: control.getLabel()
  });
  rm.openEnd();
  rm.close("div");
}
// renders: <div id="..." tabindex="0" role="switch" aria-checked="true" aria-label="Notifications">

